/* Featured members, run after part 81. Two new optional columns on `community_members`: `featured_at` (when a creator or an admin featured that member) and `featured_by` (who did). Nothing is ranked and nothing is counted: the member directory and the member's profile show the word "Featured" and that is all. A partial index reads the short list per community. No existing rows change. Until it runs, Feature answers "this needs a database update" and says so in the sheet, no mark is shown anywhere, and everything else in Members works as before. Where part 81 is missing it skips itself with a notice. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.community_members') IS NULL THEN RAISE NOTICE 'featured members: there is no community_members table, run part 81 first.'; RETURN; END IF; ALTER TABLE public.community_members ADD COLUMN IF NOT EXISTS featured_at timestamptz; ALTER TABLE public.community_members ADD COLUMN IF NOT EXISTS featured_by uuid REFERENCES auth.users(id) ON DELETE SET NULL; CREATE INDEX IF NOT EXISTS community_members_featured_idx ON public.community_members (community_id, featured_at DESC) WHERE featured_at IS NOT NULL; END $do$;
notify pgrst, 'reload schema';
